/**
 * Auto-generated asset collision pixel masks and bounding rectangle data.
 * Collision logic checks rendered non-transparent pixels only. Transparent pixels have no collision.
 */

export interface AssetBitmap {
  width: number;
  height: number;
  data: Uint8Array;
  rects: Array<[number, number, number, number]>;
}

const B64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const B64_MAP = new Uint8Array(256);
for (let i = 0; i < 64; i++) {
  B64_MAP[B64_CHARS.charCodeAt(i)] = i;
}

function decodeB64(str: string): Uint8Array {
  let len = str.length;
  if (str.endsWith("==")) len -= 2;
  else if (str.endsWith("=")) len -= 1;
  const outLen = Math.floor((str.length * 3) / 4) - (str.endsWith("==") ? 2 : str.endsWith("=") ? 1 : 0);
  const out = new Uint8Array(outLen);
  let outIdx = 0;
  for (let i = 0; i < str.length; i += 4) {
    const c0 = B64_MAP[str.charCodeAt(i)];
    const c1 = B64_MAP[str.charCodeAt(i + 1)];
    const c2 = str.charAt(i + 2) === "=" ? 0 : B64_MAP[str.charCodeAt(i + 2)];
    const c3 = str.charAt(i + 3) === "=" ? 0 : B64_MAP[str.charCodeAt(i + 3)];
    if (outIdx < outLen) out[outIdx++] = (c0 << 2) | (c1 >> 4);
    if (outIdx < outLen && str.charAt(i + 2) !== "=") out[outIdx++] = ((c1 & 15) << 4) | (c2 >> 2);
    if (outIdx < outLen && str.charAt(i + 3) !== "=") out[outIdx++] = ((c2 & 3) << 6) | c3;
  }
  return out;
}

function unpackBitmask(b64: string, width: number, height: number): Uint8Array {
  const bytes = decodeB64(b64);
  const total = width * height;
  const out = new Uint8Array(total);
  for (let i = 0; i < total; i++) {
    const byteIdx = i >> 3;
    const bitOffset = 7 - (i & 7);
    if (byteIdx < bytes.length && ((bytes[byteIdx] & (1 << bitOffset)) !== 0)) {
      out[i] = 1;
    }
  }
  return out;
}

