const BITMAP_CACHE = new Map<string, AssetBitmap>();

// Fallback solid 50x50 block for pure legacy manual obstacle tiles
const SOLID_50X50_RECTS: Array<[number, number, number, number]> = [[0, 0, 50, 50]];
const SOLID_50X50_DATA = new Uint8Array(2500).fill(1);
const DEFAULT_SOLID_BITMAP: AssetBitmap = {
  width: 50,
  height: 50,
  data: SOLID_50X50_DATA,
  rects: SOLID_50X50_RECTS,
};

export function normalizeAssetKey(key: string | undefined | null): string {
  if (!key) return "";
  const baseKey = key.includes("|") ? key.split("|")[0] : key.split("@")[0].split("^")[0];
  return ASSET_ALIASES[baseKey] || baseKey;
}

export function getAssetBitmap(key: string | undefined | null): AssetBitmap | null {
  if (!key) return null;
  const normKey = normalizeAssetKey(key);
  if (BITMAP_CACHE.has(normKey)) {
    return BITMAP_CACHE.get(normKey)!;
  }
  const raw = RAW_ASSET_DATA[normKey];
  if (raw) {
    const bmp: AssetBitmap = {
      width: raw.width,
      height: raw.height,
      data: unpackBitmask(raw.b64, raw.width, raw.height),
      rects: raw.rects,
    };
    BITMAP_CACHE.set(normKey, bmp);
    return bmp;
  }
  if (normKey === "obstacle") {
    return DEFAULT_SOLID_BITMAP;
  }
  return null;
}

export function isAssetPixelSolid(
  key: string | undefined | null,
  localX: number,
  localY: number
): boolean {
  if (!key) return false;
  const bmp = getAssetBitmap(key);
  if (!bmp) return false;
  const lx = Math.floor(localX);
  const ly = Math.floor(localY);
  if (lx < 0 || lx >= bmp.width || ly < 0 || ly >= bmp.height) {
    return false;
  }
  return bmp.data[ly * bmp.width + lx] === 1;
}

export function getAssetRects(key: string | undefined | null): Array<[number, number, number, number]> {
  if (!key) return [];
  const bmp = getAssetBitmap(key);
  return bmp ? bmp.rects : [];
}
